import{_ as r,c as a,o as t,a2 as n}from"./chunks/framework.PGES7OoM.js";const h=JSON.parse('{"title":"Curvy for wallets & Web3 product builders","description":"","frontmatter":{"rawMarkdown":"# Curvy for wallets & Web3 product builders\\n\\nCurvy enables wallets and Web3 applications to integrate privacy flows directly into their product with **zero upfront cost** and minimal engineering effort.\\n\\nWith just a few lines of code through the Curvy SDK, you can offer your users:\\n\\n- Private receiving via ENS-compatible usernames and stealth addresses\\n- ZK-powered private execution flows  \\n- Shielding and unshielding capabilities  \\n- Compliance-aware privacy infrastructure  \\n\\nThis way, privacy becomes a native feature of your app integrated within your product.\\n\\n## How integration works\\n\\nCurvy provides:\\n\\n- open-source SDK\\n- smart contract infrastructure\\n- multi-chain compatibility\\n- modular privacy components\\n\\n## Partnership program\\n\\nWallets and Web3 products can apply to join the Curvy Partnership Program by contacting:\\n\\n**<hey@curvy.box>**\\n\\n> [!TIP]\\n> As a partner, you can earn a share of protocol fees generated by your users’ private transactions.\\n\\n## Partner benefits\\n\\nIn addition to revenue share, partners receive:\\n\\n- dedicated collaboration channel between our teams\\n- prioritized feature requests\\n- additional chain support (based on demand)\\n- token support expansion\\n- execution flows tailored to partner use cases\\nWe align product development with real ecosystem needs.\\n\\n## Why integrate Curvy?\\n\\n- Non-custodial architecture  \\n- Compliance-aware design  \\n- Enterprise-ready privacy layer  \\n- Revenue-generating integration  \\n- Minimal engineering overhead  \\n","rawMarkdownPath":"/_raw/for-businesses/for-wallets-and-web3-products.md","rawMarkdownTitle":"Curvy for wallets & Web3 product builders","rawMarkdownUrl":"https://docs.curvy.box/_raw/for-businesses/for-wallets-and-web3-products.md"},"headers":[],"relativePath":"for-businesses/for-wallets-and-web3-products.md","filePath":"for-businesses/for-wallets-and-web3-products.md","lastUpdated":1773768298000}'),i={name:"for-businesses/for-wallets-and-web3-products.md"};function o(s,e,l,u,c,p){return t(),a("div",null,[...e[0]||(e[0]=[n("",17)])])}const b=r(i,[["render",o]]);export{h as __pageData,b as default};
